<script setup>
import { computed } from 'vue'
const props=defineProps({overview:{type:Object,required:true}})
const emit=defineEmits(['select-view'])
const tickets=computed(()=>props.overview.ticket_performance||[])
const sources=computed(()=>Array.isArray(props.overview.buyer_sources)?props.overview.buyer_sources:[])
const points=computed(()=>props.overview.sales_trend?.points||[])
const integer=(value)=>new Intl.NumberFormat('en-NG').format(Number(value||0))
const money=(minor)=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(Number(minor||0)/100)
const peak=(hour)=>{if(hour===null||hour===undefined)return '—';const value=Number(hour);if(!Number.isInteger(value))return '—';const start=new Date();start.setHours(value,0,0,0);const end=new Date(start);end.setHours(value+1);const formatter=new Intl.DateTimeFormat('en-NG',{hour:'numeric'});return `${formatter.format(start)}–${formatter.format(end)}`}
const chart=computed(()=>{const values=points.value;if(!values.length)return {line:'',area:'',labels:[]};const left=14,bottom=110,top=12,width=552,max=Math.max(1,...values.map((p)=>Number(p.tickets_sold||0)));const coords=values.map((p,index)=>({x:Number((values.length===1?left:left+index/(values.length-1)*width).toFixed(2)),y:Number((bottom-Number(p.tickets_sold||0)/max*(bottom-top)).toFixed(2))}));const line=coords.map((p)=>`${p.x},${p.y}`).join(' ');const labels=[0,Math.floor((values.length-1)/2),values.length-1].filter((v,i,a)=>a.indexOf(v)===i).map((index)=>({x:coords[index].x,text:new Intl.DateTimeFormat('en-NG',{month:'short',day:'numeric'}).format(new Date(`${values[index].date}T00:00:00`))}));return {line,area:`${coords[0].x},${bottom} ${line} ${coords.at(-1).x},${bottom}`,labels}})
</script>
<template><div class="manage-view active" id="mv-overview"><div class="sections-wrap overview-wrap"><section><article class="card generated-ticket-performance-card"><div class="overview-card-head"><h3>How your tickets are doing</h3><p>See what has sold and what is still available.</p></div><div v-if="tickets.length" class="traffic-rows overview-traffic generated-ticket-rows"><div v-for="ticket in tickets" :key="ticket.ticket_type_id" class="traffic-row"><div class="traffic-info"><div class="traffic-name">{{ ticket.name }}</div><div class="traffic-count">{{ integer(ticket.sold_units) }} sold · {{ integer(ticket.available_units) }} left</div><div class="traffic-bar-wrap"><div class="traffic-bar-track"><div class="traffic-bar-fill fill-pink" :style="{width:`${Math.min(100,Number(ticket.sold_percent||0))}%`}"></div></div></div></div><div class="traffic-pct">{{ ticket.sold_percent }}%</div></div></div><div v-else class="dashboard-data-empty">No ticket types yet.</div></article></section><section v-if="sources.length"><article class="card generated-ticket-performance-card"><div class="overview-card-head"><h3>Where sales came from</h3><p>Revenue credited to the last tracked link before checkout.</p></div><div class="traffic-rows overview-traffic"><div v-for="source in sources" :key="`${source.channel}-${source.label}`" class="traffic-row"><div class="traffic-info"><div class="traffic-name">{{ source.label }}</div><div class="traffic-count">{{ integer(source.tickets_sold) }} tickets · {{ money(source.revenue_minor) }}</div><div class="traffic-bar-wrap"><div class="traffic-bar-track"><div class="traffic-bar-fill fill-pink" :style="{width:`${Math.min(100,Number(source.revenue_percent||0))}%`}"></div></div></div></div><div class="traffic-pct">{{ source.revenue_percent }}%</div></div></div><button type="button" class="overview-source-link" @click="emit('select-view','share')">See all sharing links</button></article></section><section><div class="section-title">Sales trend</div><div class="card"><div class="chart-wrap"><div class="chart-head"><div><div class="chart-head-title">Tickets bought per day</div><div class="chart-head-sub">Last 30 days</div></div></div><svg v-if="chart.line" class="chart-svg" viewBox="0 0 580 130" fill="none" role="img" aria-label="Tickets sold over the last 30 days"><line x1="0" y1="110" x2="580" y2="110" stroke="currentColor" opacity=".08"/><polygon :points="chart.area" fill="currentColor" opacity=".06"/><polyline :points="chart.line" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/><text v-for="label in chart.labels" :key="`${label.x}-${label.text}`" :x="label.x" y="127" text-anchor="middle" class="chart-axis-label">{{ label.text }}</text></svg></div></div></section><section class="overview-mini-metrics"><article class="mini-metric-card"><div class="stat-cell-label">Average spend per buyer</div><div class="mini-metric-value">{{ money(overview.buying_patterns?.average_spend_per_buyer_minor) }}</div></article><article class="mini-metric-card"><div class="stat-cell-label">Best sales day</div><div class="mini-metric-value">{{ overview.buying_patterns?.best_sales_day || '—' }}</div></article><article class="mini-metric-card"><div class="stat-cell-label">Peak buying time</div><div class="mini-metric-value">{{ peak(overview.buying_patterns?.peak_buying_hour) }}</div></article></section></div></div></template>
<style scoped>.dashboard-data-empty{padding:24px 0 4px;color:var(--color-muted);font-size:.82rem}.chart-svg{color:var(--color-accent)}.chart-axis-label{fill:var(--color-muted);font-size:9px}.overview-source-link{margin-top:16px;border:0;padding:0;background:transparent;color:var(--color-accent);font:inherit;font-size:.75rem;font-weight:700;cursor:pointer}</style>
